import json

# Generate the solution grid based on demo pattern
# Demo output rows divisible by 5 get columns {0,3,6,9,12,15,18,21} + {13,14,16,17}
# Other rows get the same + extra

# For test input with special values at (0,27), (11,24), (22,25)
grid = [row[:] for row in [[2]*29 for _ in range(24)]]

# Fill columns {0,3,6,9,12,15,18,21} + {13,14,16,17} for rows 0,11,22
cols1 = {0, 3, 6, 9, 12, 15, 18, 21}
cols2 = {13, 14, 16, 17}

for r in [0, 11, 22]:
    for c in cols1 | cols2:
        grid[r][c] = 2

# Fill columns {0,3,6,9,12,15,18} for rows not in [0,11,22]
for r in range(24):
    if r not in [0, 11, 22]:
        for c in {0, 3, 6, 9, 12, 15, 18}:
            grid[r][c] = 2

# Set special positions (where input has 0)
grid[0][27] = 0
grid[11][24] = 0
grid[22][25] = 0

print(json.dumps({"action": "submit", "grid": grid}))

import json

# Create solution grid for test input
# Test input has 24x29 grid with 3s, markers at (0,27), (11,24), (22,25)
# Output should have 0s at marker positions and follow pattern

grid = [[0] * 29 for _ in range(24)]  # Start with all 0s (we'll overwrite with 3)

# Regular pattern: columns 0, 3, 6, 9, 12, 15, 18
regular_cols = {0, 3, 6, 9, 12, 15, 18}

# Special pattern: adds 13, 14, 16, 17, 19, 20
special_cols = regular_cols | {13, 14, 16, 17, 19, 20}

# Marker rows: 0, 11, 22 use special pattern
# Other rows use regular pattern
marker_rows = {0, 11, 22}

for r in range(24):
    if r in marker_rows:
        # Special pattern - use cols 0,3,6,9,12,15,18, 13,14,16,17,19,20
        for c in special_cols:
            grid[r][c] = 3  # Use 3 as marker value in output (replaces 0s)
    else:
        # Regular pattern
        for c in regular_cols:
            grid[r][c] = 3

# Set actual marker positions to 0
grid[0][27] = 0
grid[11][24] = 0
grid[22][25] = 0

print(json.dumps({"action": "submit", "grid": grid}))

